        options: [
          'The hook created expectations that the body tweets didn\'t deliver on, causing readers to abandon the thread mid-way',
          'The thread was published at the wrong time of day',
          'The topic wasn\'t interesting to anyone',
          'The CTA was too aggressive'
        ],
        correct: 0,
